INSERT INTO chat_message (chat_message_id, chat_room_id, sender_id, message_type, content, image_file_key, created_at) VALUES
    (1, 1, 89, 'TEXT', '안녕하세요, 천호 새봄공인중개사사무소 황수빈 중개사입니다. 수원시 영통구 광교중앙로25길 56 매물 중개 신청 확인했습니다.', NULL, '2024-09-02 08:23:05'),
    (2, 1, 2, 'TEXT', '네 안녕하세요. 잘 부탁드립니다.', NULL, '2024-09-02 08:40:05'),
    (3, 1, 89, 'TEXT', '사진 촬영이랑 현장 확인 때문에 한번 방문하려고 하는데 언제가 편하실까요?', NULL, '2024-09-02 08:45:05'),
    (4, 1, 2, 'TEXT', '이번 주 토요일 오전 괜찮습니다.', NULL, '2024-09-02 09:17:05'),
    (5, 1, 89, 'TEXT', '네, 토요일 10시에 방문하겠습니다. 현관 비밀번호는 당일 문자로 부탁드립니다.', NULL, '2024-09-03 10:16:05'),
    (6, 1, 89, 'IMAGE', NULL, 'chat-images/2024/09/233b3527d42d572bf906678b180c355f.jpg', '2024-09-04 13:03:05'),
    (7, 2, 32, 'TEXT', '안녕하세요. 수원시 영통구 광교중앙로25길 56 매물 보고 연락드렸습니다. 아직 계약 가능한가요?', NULL, '2024-09-12 07:06:58'),
    (8, 2, 89, 'TEXT', '네 안녕하세요. 현재 계약 가능한 매물입니다.', NULL, '2024-09-12 07:16:58'),
    (9, 2, 32, 'TEXT', '직접 보고 싶은데 이번 주말에 방문 가능할까요?', NULL, '2024-09-12 07:20:58'),
    (10, 2, 89, 'TEXT', '토요일 오후 2시 가능합니다. 광교중앙역 근처에서 뵙겠습니다.', NULL, '2024-09-13 08:42:58'),
    (11, 2, 32, 'TEXT', '집 너무 마음에 들어서 계약하고 싶습니다.', NULL, '2024-09-13 09:09:58'),
    (12, 2, 89, 'TEXT', '네, 집주인분과 일정 맞춰서 계약서 작성 날짜 알려드리겠습니다.', NULL, '2024-09-13 09:40:58'),
    (13, 2, 32, 'TEXT', '감사합니다!', NULL, '2024-09-13 09:49:58'),
    (14, 3, 68, 'TEXT', '안녕하세요. 입주 가능 날짜가 언제인가요?', NULL, '2024-09-14 00:17:59'),
    (15, 3, 89, 'TEXT', '다음 달 초부터 입주 가능합니다.', NULL, '2024-09-14 00:32:59'),
    (16, 3, 89, 'IMAGE', NULL, 'chat-images/2024/09/773218187c0ac93153e206401f3579b5.jpg', '2024-09-15 07:02:59'),
    (17, 3, 89, 'TEXT', '최근에 도배랑 장판 새로 한 사진입니다.', NULL, '2024-09-15 18:38:59'),
    (18, 3, 68, 'TEXT', '깔끔하네요. 전입신고랑 확정일자 받을 수 있죠?', NULL, '2024-09-17 04:41:59'),
    (19, 3, 89, 'TEXT', '네, 둘 다 가능합니다.', NULL, '2024-09-17 05:02:59'),
    (20, 1, 89, 'TEXT', '사장님, 실거주 희망하시는 임차인분이 계약 의사를 밝히셨습니다. 조건은 등록하신 그대로입니다.', NULL, '2024-10-08 14:59:40'),
    (21, 1, 2, 'TEXT', '좋습니다. 계약 진행해 주세요.', NULL, '2024-10-08 15:16:40'),
    (22, 1, 89, 'TEXT', '계약서 작성 일정 조율해서 다시 연락드리겠습니다.', NULL, '2024-10-08 15:34:40'),
    (23, 4, 88, 'TEXT', '안녕하세요, 고속터미널 으뜸공인중개사사무소 이가은 중개사입니다. 영등포구 여의대방로21길 8 매물 중개 신청 확인했습니다.', NULL, '2024-11-06 22:30:10'),
    (24, 4, 3, 'TEXT', '네 안녕하세요. 잘 부탁드립니다.', NULL, '2024-11-07 16:44:10'),
    (25, 4, 88, 'TEXT', '사진 촬영이랑 현장 확인 때문에 한번 방문하려고 하는데 언제가 편하실까요?', NULL, '2024-11-07 17:17:10'),
    (26, 4, 3, 'TEXT', '이번 주 토요일 오전 괜찮습니다.', NULL, '2024-11-08 15:05:10'),
    (27, 5, 33, 'TEXT', '안녕하세요. 영등포구 여의대방로21길 8 매물 보고 연락드렸습니다. 아직 계약 가능한가요?', NULL, '2024-11-09 11:19:00'),
    (28, 5, 88, 'TEXT', '네 안녕하세요. 현재 계약 가능한 매물입니다.', NULL, '2024-11-09 11:34:00'),
    (29, 5, 33, 'TEXT', '직접 보고 싶은데 이번 주말에 방문 가능할까요?', NULL, '2024-11-09 11:48:00'),
    (30, 5, 88, 'TEXT', '토요일 오후 2시 가능합니다. 대방역 근처에서 뵙겠습니다.', NULL, '2024-11-09 11:58:00'),
    (31, 5, 33, 'TEXT', '집 너무 마음에 들어서 계약하고 싶습니다.', NULL, '2024-11-09 12:18:00'),
    (32, 5, 88, 'TEXT', '네, 집주인분과 일정 맞춰서 계약서 작성 날짜 알려드리겠습니다.', NULL, '2024-11-09 12:48:00'),
    (33, 5, 33, 'TEXT', '감사합니다!', NULL, '2024-11-09 13:25:00'),
    (34, 6, 74, 'TEXT', '혹시 반려동물 키워도 되는 집인가요? 소형견 한 마리 있습니다.', NULL, '2024-11-12 01:30:14'),
    (35, 6, 88, 'TEXT', '집주인분께 확인해 보고 말씀드리겠습니다.', NULL, '2024-11-12 01:38:14'),
    (36, 6, 88, 'TEXT', '확인해 보니 소형견은 괜찮다고 하십니다.', NULL, '2024-11-13 03:59:14'),
    (37, 6, 74, 'TEXT', '감사합니다! 방문 일정 잡고 싶어요.', NULL, '2024-11-13 04:35:14'),
    (38, 4, 88, 'TEXT', '사장님, 실거주 희망하시는 임차인분이 계약 의사를 밝히셨습니다. 조건은 등록하신 그대로입니다.', NULL, '2024-11-24 15:32:36'),
    (39, 4, 3, 'TEXT', '좋습니다. 계약 진행해 주세요.', NULL, '2024-11-26 01:14:36'),
    (40, 4, 88, 'TEXT', '계약서 작성 일정 조율해서 다시 연락드리겠습니다.', NULL, '2024-11-27 02:02:36'),
    (41, 7, 83, 'TEXT', '안녕하세요, 홍대입구 한빛공인중개사사무소 우진영 중개사입니다. 용산구 한강대로 68 매물 중개 신청 확인했습니다.', NULL, '2024-12-17 16:46:23'),
