    (567, 97, 55, 'TEXT', '깔끔하네요. 전입신고랑 확정일자 받을 수 있죠?', NULL, '2026-08-18 03:14:36'),
    (568, 97, 87, 'TEXT', '네, 둘 다 가능합니다.', NULL, '2026-08-18 03:34:36'),
    (569, 98, 47, 'TEXT', '안녕하세요. 영등포구 여의대방로 155 매물 보고 연락드렸습니다. 아직 계약 가능한가요?', NULL, '2026-08-18 21:25:24'),
    (570, 98, 88, 'TEXT', '네 안녕하세요. 현재 계약 가능한 매물입니다.', NULL, '2026-08-18 21:56:24'),
    (571, 98, 47, 'TEXT', '직접 보고 싶은데 이번 주말에 방문 가능할까요?', NULL, '2026-08-18 22:15:24'),
    (572, 98, 88, 'TEXT', '토요일 오후 2시 가능합니다. 대방역 근처에서 뵙겠습니다.', NULL, '2026-08-19 10:41:24'),
    (573, 98, 47, 'TEXT', '집 너무 마음에 들어서 계약하고 싶습니다.', NULL, '2026-08-19 10:45:24'),
    (574, 98, 88, 'TEXT', '네, 집주인분과 일정 맞춰서 계약서 작성 날짜 알려드리겠습니다.', NULL, '2026-08-19 11:18:24'),
    (575, 98, 47, 'TEXT', '감사합니다!', NULL, '2026-08-19 11:44:24'),
    (576, 89, 88, 'TEXT', '사장님, 실거주 희망하시는 임차인분이 계약 의사를 밝히셨습니다. 조건은 등록하신 그대로입니다.', NULL, '2026-08-22 01:09:43'),
    (577, 89, 17, 'TEXT', '좋습니다. 계약 진행해 주세요.', NULL, '2026-08-22 01:46:43'),
    (578, 89, 88, 'TEXT', '계약서 작성 일정 조율해서 다시 연락드리겠습니다.', NULL, '2026-08-22 02:09:43'),
    (579, 99, 88, 'TEXT', '안녕하세요, 고속터미널 으뜸공인중개사사무소 이가은 중개사입니다. 양천구 목동동로13길 14 매물 중개 신청 확인했습니다.', NULL, '2026-08-26 02:36:53'),
    (580, 99, 21, 'TEXT', '네 안녕하세요. 잘 부탁드립니다.', NULL, '2026-08-27 02:59:53'),
    (581, 99, 88, 'TEXT', '사진 촬영이랑 현장 확인 때문에 한번 방문하려고 하는데 언제가 편하실까요?', NULL, '2026-08-27 03:36:53'),
    (582, 99, 21, 'TEXT', '이번 주 토요일 오전 괜찮습니다.', NULL, '2026-08-27 04:07:53'),
    (583, 99, 88, 'TEXT', '네, 토요일 10시에 방문하겠습니다. 현관 비밀번호는 당일 문자로 부탁드립니다.', NULL, '2026-08-27 04:12:53'),
    (584, 99, 88, 'IMAGE', NULL, 'chat-images/2026/08/2ee47a59122ad4f6d073a3c2ec1e57fa.jpg', '2026-08-27 04:14:53'),
    (585, 99, 88, 'TEXT', '사진이랑 상세 정보 등록 완료했습니다. 문의 들어오면 바로 말씀드릴게요.', NULL, '2026-08-27 21:09:53'),
    (586, 99, 21, 'TEXT', '감사합니다. 수고하세요.', NULL, '2026-08-27 21:30:53'),
    (587, 100, 88, 'TEXT', '안녕하세요, 고속터미널 으뜸공인중개사사무소 이가은 중개사입니다. 동작구 노량진로4길 62 매물 중개 신청 확인했습니다.', NULL, '2026-08-28 01:08:59'),
    (588, 100, 18, 'TEXT', '네 안녕하세요. 잘 부탁드립니다.', NULL, '2026-08-28 01:43:59'),
    (589, 100, 88, 'TEXT', '사진 촬영이랑 현장 확인 때문에 한번 방문하려고 하는데 언제가 편하실까요?', NULL, '2026-08-28 01:45:59'),
    (590, 100, 18, 'TEXT', '이번 주 토요일 오전 괜찮습니다.', NULL, '2026-08-28 01:56:59'),
    (591, 101, 35, 'TEXT', '혹시 반려동물 키워도 되는 집인가요? 소형견 한 마리 있습니다.', NULL, '2026-08-28 16:33:22'),
    (592, 101, 86, 'TEXT', '집주인분께 확인해 보고 말씀드리겠습니다.', NULL, '2026-08-28 16:56:22'),
    (593, 101, 86, 'TEXT', '확인해 보니 소형견은 괜찮다고 하십니다.', NULL, '2026-08-28 17:03:22'),
    (594, 101, 35, 'TEXT', '감사합니다! 방문 일정 잡고 싶어요.', NULL, '2026-08-28 17:21:22'),
    (595, 102, 36, 'TEXT', '안녕하세요. 관악구 신림로16길 18 매물 보고 연락드렸습니다. 아직 계약 가능한가요?', NULL, '2026-08-28 22:19:35'),
    (596, 102, 83, 'TEXT', '네 안녕하세요. 현재 계약 가능한 매물입니다.', NULL, '2026-08-28 22:25:35'),
    (597, 103, 79, 'TEXT', '혹시 반려동물 키워도 되는 집인가요? 소형견 한 마리 있습니다.', NULL, '2026-08-29 03:11:57'),
    (598, 103, 85, 'TEXT', '집주인분께 확인해 보고 말씀드리겠습니다.', NULL, '2026-08-29 03:49:57'),
    (599, 103, 85, 'TEXT', '확인해 보니 소형견은 괜찮다고 하십니다.', NULL, '2026-08-29 03:57:57'),
