    (673, 120, 88, 'TEXT', '네 안녕하세요. 현재 계약 가능한 매물입니다.', NULL, '2026-10-05 20:43:08'),
    (674, 120, 48, 'TEXT', '직접 보고 싶은데 이번 주말에 방문 가능할까요?', NULL, '2026-10-05 21:00:08'),
    (675, 120, 88, 'TEXT', '토요일 오후 2시 가능합니다. 노량진역 근처에서 뵙겠습니다.', NULL, '2026-10-05 21:29:08'),
    (676, 120, 48, 'TEXT', '집 너무 마음에 들어서 계약하고 싶습니다.', NULL, '2026-10-05 22:00:08'),
    (677, 120, 88, 'TEXT', '네, 집주인분과 일정 맞춰서 계약서 작성 날짜 알려드리겠습니다.', NULL, '2026-10-05 22:37:08'),
    (678, 120, 48, 'TEXT', '감사합니다!', NULL, '2026-10-05 22:50:08'),
    (679, 121, 71, 'TEXT', '안녕하세요. 입주 가능 날짜가 언제인가요?', NULL, '2026-10-06 02:01:16'),
    (680, 121, 85, 'TEXT', '다음 달 초부터 입주 가능합니다.', NULL, '2026-10-06 02:12:16'),
    (681, 121, 85, 'IMAGE', NULL, 'chat-images/2026/10/cbd6d511366e0c0bd72d643a972ecfca.jpg', '2026-10-06 02:18:16'),
    (682, 121, 85, 'TEXT', '최근에 도배랑 장판 새로 한 사진입니다.', NULL, '2026-10-06 02:24:16'),
    (683, 121, 71, 'TEXT', '깔끔하네요. 전입신고랑 확정일자 받을 수 있죠?', NULL, '2026-10-06 02:53:16'),
    (684, 121, 85, 'TEXT', '네, 둘 다 가능합니다.', NULL, '2026-10-06 03:10:16'),
    (685, 122, 49, 'TEXT', '안녕하세요. 성북구 동소문로23길 61 매물 보고 연락드렸습니다. 아직 계약 가능한가요?', NULL, '2026-10-06 13:13:21'),
    (686, 122, 85, 'TEXT', '네 안녕하세요. 현재 계약 가능한 매물입니다.', NULL, '2026-10-06 13:20:21'),
    (687, 123, 56, 'TEXT', '등기부등본상 근저당 있는지 확인 가능할까요?', NULL, '2026-10-06 15:44:15'),
    (688, 123, 88, 'TEXT', '현재 근저당은 없습니다. 매물 상세에서 등기부등본 확인 결과도 보실 수 있습니다.', NULL, '2026-10-06 15:52:15'),
    (689, 123, 56, 'TEXT', '네 확인했습니다. 감사합니다.', NULL, '2026-10-06 16:19:15'),
    (690, 122, 49, 'TEXT', '직접 보고 싶은데 이번 주말에 방문 가능할까요?', NULL, '2026-10-08 05:02:21'),
    (691, 122, 85, 'TEXT', '토요일 오후 2시 가능합니다. 성신여대입구역 근처에서 뵙겠습니다.', NULL, '2026-10-08 05:18:21'),
    (692, 122, 49, 'TEXT', '집 너무 마음에 들어서 계약하고 싶습니다.', NULL, '2026-10-08 05:49:21'),
    (693, 122, 85, 'TEXT', '네, 집주인분과 일정 맞춰서 계약서 작성 날짜 알려드리겠습니다.', NULL, '2026-10-09 15:22:21'),
    (694, 122, 49, 'TEXT', '감사합니다!', NULL, '2026-10-10 04:57:21'),
    (695, 100, 88, 'TEXT', '사장님, 실거주 희망하시는 임차인분이 계약 의사를 밝히셨습니다. 조건은 등록하신 그대로입니다.', NULL, '2026-10-10 14:29:45'),
    (696, 100, 18, 'TEXT', '좋습니다. 계약 진행해 주세요.', NULL, '2026-10-11 00:31:45'),
    (697, 100, 88, 'TEXT', '계약서 작성 일정 조율해서 다시 연락드리겠습니다.', NULL, '2026-10-11 13:45:45'),
    (698, 105, 85, 'TEXT', '사장님, 실거주 희망하시는 임차인분이 계약 의사를 밝히셨습니다. 조건은 등록하신 그대로입니다.', NULL, '2026-10-16 15:23:27'),
