    (1, 38, 44, 'FALSE_LISTING', '사진과 실제 집이 전혀 다릅니다. 방 크기도 광고보다 훨씬 작고 옵션도 없습니다.', '2026-01-23 17:04:35'),
    (2, 50, 76, 'RISKY_PROPERTY', '전세가가 매매 시세에 거의 육박하는데 근저당까지 있다고 들었습니다. 위험 매물인지 확인 부탁드립니다.', '2026-03-24 00:58:00'),
    (3, 97, 55, 'RISK_INFO', '중개사가 등기부등본 확인을 계속 미루면서 가계약금 입금을 재촉합니다.', '2026-08-18 04:32:36');

