INSERT INTO as_request (as_request_id, property_id, tenant_id, content, as_status, created_at, updated_at) VALUES
    (1, 5, 36, '안방 천장 모서리에 곰팡이가 생겼습니다. 결로 때문인 것 같습니다.', 'COMPLETED', '2025-09-23 19:29:05', '2025-09-30 22:29:05'),
    (2, 7, 38, '세탁기 배수 호스 연결 부위에서 물이 샙니다.', 'COMPLETED', '2025-11-14 14:38:27', '2025-11-21 19:38:27'),
    (3, 1, 32, '작은방 콘센트 하나에 전기가 들어오지 않습니다.', 'COMPLETED', '2026-01-15 19:56:14', '2026-01-25 19:56:14'),
    (4, 2, 33, '베란다 창문 샷시가 잘 안 닫히고 틈으로 찬바람이 들어옵니다.', 'COMPLETED', '2026-03-20 13:50:04', '2026-03-29 16:50:04'),
    (5, 14, 44, '보일러 온수가 미지근하게만 나옵니다. 점검 부탁드립니다.', 'COMPLETED', '2026-04-03 20:25:28', '2026-04-12 00:25:28'),
    (6, 22, 45, '화장실 환풍기가 작동하지 않습니다.', 'COMPLETED', '2026-06-23 17:02:28', '2026-07-01 19:02:28'),
    (7, 28, 46, '인덕션 왼쪽 화구가 켜지지 않습니다.', 'COMPLETED', '2026-07-28 12:00:56', '2026-08-06 15:00:56'),
    (8, 9, 39, '거실 에어컨을 켜면 실내기에서 물이 떨어집니다.', 'COMPLETED', '2026-08-02 16:19:08', '2026-08-09 19:19:08'),
    (9, 11, 42, '변기 물이 멈추지 않고 계속 흐르는 소리가 납니다.', 'COMPLETED', '2026-08-20 17:26:37', '2026-08-27 14:26:37'),
    (10, 3, 34, '현관 도어락 배터리를 새로 넣어도 자꾸 오작동합니다.', 'COMPLETED', '2026-09-12 13:29:08', '2026-09-19 23:29:08'),
    (11, 4, 35, '욕실 세면대 배수가 잘 안 됩니다. 물이 천천히 빠지고 하수구 냄새도 올라옵니다.', 'RECEIVED', '2026-09-18 20:41:09', '2026-09-18 20:41:09'),
    (12, 10, 41, '주방 싱크대 하부장 쪽에서 물이 샙니다. 바닥이 계속 젖어 있습니다.', 'IN_PROGRESS', '2026-09-23 16:57:14', '2026-09-25 06:57:14');

