    (1, 14, 44, 14, 'LISTING_MISMATCH', '매물 사진에는 없던 벽지 얼룩과 곰팡이가 입주 후에 확인됐습니다.', 88, '2026-03-10 11:00:00', '2026-03-09 19:12:00'),
    (2, 1, 2, 32, 'BAD_TENANT', '밤마다 소음 민원이 반복돼서 관리사무소에서 계속 연락이 옵니다.', 89, '2026-08-13 09:40:00', '2026-08-12 22:47:00'),
    (3, 4, 35, 5, 'AS_NO_RESPONSE', '9월 18일에 요청한 AS에 한 달 가까이 답변이 없습니다.', 87, '2026-10-06 10:00:00', '2026-10-05 21:03:00'),
    (4, 8, 10, 40, 'RENT_UNPAID', '9월, 10월 두 달 연속으로 월세가 들어오지 않았습니다. 연락도 잘 안 됩니다.', 86, '2026-10-14 09:30:00', '2026-10-13 10:20:00'),
