INSERT INTO claim_comment (claim_comment_id, claim_id, author_id, content, created_at) VALUES
    (1, 1, 88, '임대인과 협의해서 이번 주 토요일에 도배를 새로 하기로 했습니다.', '2026-03-12 15:40:00'),
    (2, 1, 88, '도배 완료 확인했습니다.', '2026-03-16 10:05:00'),
    (3, 2, 89, '임차인에게 주의를 요청했습니다. 이후 민원이 더 들어오는지 지켜보겠습니다.', '2026-08-16 14:00:00'),
    (4, 4, 86, '임차인과 통화했습니다. 이번 달 말까지 밀린 월세를 모두 납부하겠다고 합니다.', '2026-10-15 16:05:00');

