INSERT INTO risk_info (risk_info_id, target_type, target_user_id, target_property_id, reason_type, detail, evidence_file_key, risk_status, registered_by, update_reason, released_at, created_at, updated_at) VALUES
    (1, 'USER', 22, NULL, 'FALSE_LISTING', '실제와 다른 면적과 옵션으로 매물을 등록해 허위 매물 신고가 접수됨. 현장 확인 결과 신고 내용과 일치.', 'risk-evidence/2026/01/bc57a0e5022c98b875466e635200bc1f.jpg', 'REGISTERED', 1, NULL, NULL, '2026-01-31 12:07:40', '2026-01-31 12:07:40'),
    (2, 'PROPERTY', NULL, 16, 'NO_PROPERTY_IMAGE', '중개 수락 후 7일이 지나도록 매물 사진이 등록되지 않음.', NULL, 'REGISTERED', 1, NULL, NULL, '2026-02-17 10:40:17', '2026-02-17 10:40:17'),
    (3, 'USER', 87, NULL, 'AGENT_CHANGE_HISTORY', '최근 3개월 동안 중개 중인 매물 4건에서 임대인이 중개사 교체를 요청함.', NULL, 'RELEASED', 1, '임대인 개인 사정에 따른 교체로 소명 자료 확인 후 해제', '2026-05-10 15:00:00', '2026-04-02 11:30:00', '2026-05-10 15:00:00'),
    (4, 'PROPERTY', NULL, 21, 'MORTGAGE_RISK', '등기부등본 을구에 채권최고액 1억원의 근저당권이 설정되어 있음. 보증금 대비 선순위 채권 비율이 높아 보증금 반환 위험이 큼.', 'risk-evidence/2026/04/d607bf70e7e71fd17c7e35be34faec35.pdf', 'REGISTERED', 1, NULL, NULL, '2026-04-15 11:11:03', '2026-04-15 11:11:03'),
    (5, 'PROPERTY', NULL, 31, 'MORTGAGE_RISK', '등기부등본 을구에 채권최고액 3억 3,000만원의 근저당권이 설정되어 있음. 보증금 대비 선순위 채권 비율이 높아 보증금 반환 위험이 큼.', 'risk-evidence/2026/06/6c9c216cac4a516c7f931fbc059b9ebc.pdf', 'REGISTERED', 1, NULL, NULL, '2026-06-23 15:11:15', '2026-06-23 15:11:15'),
    (6, 'USER', 27, NULL, 'DEPOSIT_UNPAID', '이전 임차인에게 보증금 3,000만원을 계약 종료 후 4개월 동안 반환하지 않음. 임차권등기명령 신청 이력 확인.', 'risk-evidence/2026/07/e35324c4f9130fcef1e34b244210510b.pdf', 'REGISTERED', 1, NULL, NULL, '2026-07-08 14:20:00', '2026-07-08 14:20:00'),
    (7, 'PROPERTY', NULL, 39, 'MORTGAGE_RISK', '등기부등본 을구에 채권최고액 2,000만원의 근저당권이 설정되어 있음. 보증금 대비 선순위 채권 비율이 높아 보증금 반환 위험이 큼.', 'risk-evidence/2026/08/381c30d0f0e01899835f505c17bc8251.pdf', 'REGISTERED', 1, NULL, NULL, '2026-08-29 15:55:49', '2026-08-29 15:55:49'),
    (8, 'USER', 40, NULL, 'RENT_OVERDUE', '9월, 10월 월세가 최종 재시도까지 모두 실패해 2개월 연속 연체 상태.', NULL, 'CANDIDATE', NULL, NULL, NULL, '2026-10-12 09:02:00', '2026-10-12 09:02:00');

